    <section class="card p-6"><h2 class="mb-4 text-lg font-black">3. Invoice Items</h2><div class="max-w-full overflow-x-auto"><table class="w-full min-w-[850px] text-sm"><thead><tr><th class="p-2 text-left">Description</th><th class="p-2 text-left">HSN/SAC</th><th class="p-2 text-left">Required Workers / Qty</th><th class="p-2 text-left">Unit</th><th class="p-2 text-left">Rate</th><th class="p-2 text-left">Amount</th><th></th></tr></thead><tbody id="itemRows">@foreach(old('items',$invoice->items->toArray()) as $i=>$item)<tr class="item-row"><td class="p-1"><input required name="items[{{ $i }}][description]" value="{{ data_get($item,'description') }}"></td><td class="p-1"><input name="items[{{ $i }}][hsn_sac_code]" value="{{ data_get($item,'hsn_sac_code') }}"></td><td class="p-1"><input class="qty" required min="0.01" step="0.01" type="number" name="items[{{ $i }}][quantity]" value="{{ data_get($item,'quantity',1) }}"></td><td class="p-1"><input name="items[{{ $i }}][unit]" value="{{ data_get($item,'unit') }}"></td><td class="p-1"><input class="rate" required min="0" step="0.01" type="number" name="items[{{ $i }}][rate]" value="{{ data_get($item,'rate',0) }}"></td><td class="p-1 font-bold amount">0.00</td><td class="p-1"><button type="button" class="remove-row text-red-600">Remove</button><input type="hidden" name="items[{{ $i }}][service_id]" value="{{ data_get($item,'service_id') }}"></td></tr>@endforeach</tbody></table></div><button type="button" id="addItem" class="btn-secondary mt-4">+ Add Item</button></section>
    <section class="card p-6"><h2 class="mb-4 text-lg font-black">4. Tax / GST</h2><div class="grid gap-4 md:grid-cols-3"><div><label>Discount Type</label><select name="discount_type"><option value="">No discount</option><option value="fixed" @selected(old('discount_type',$invoice->discount_type)=='fixed')>Fixed</option><option value="percentage" @selected(old('discount_type',$invoice->discount_type)=='percentage')>Percentage</option></select></div><div><label>Discount Value</label><input type="number" step="0.01" min="0" name="discount_value" value="{{ old('discount_value',$invoice->discount_value ?? 0) }}"></div><div><label>Tax Type *</label><select name="tax_type"><option value="none" @selected(old('tax_type',$invoice->tax_type)=='none')>No GST</option><option value="intra_state" @selected(old('tax_type',$invoice->tax_type)=='intra_state')>CGST + SGST</option><option value="inter_state" @selected(old('tax_type',$invoice->tax_type)=='inter_state')>IGST</option></select></div><div><label>Overall GST Rate %</label><input required type="number" min="0" max="100" step="0.01" name="tax_rate" value="{{ old('tax_rate',$invoice->tax_rate ?? 0) }}"></div><div><label>CGST Rate %</label><input type="number" min="0" max="100" step="0.01" name="cgst_rate" value="{{ old('cgst_rate',$invoice->cgst_rate ?? 0) }}"></div><div><label>SGST Rate %</label><input type="number" min="0" max="100" step="0.01" name="sgst_rate" value="{{ old('sgst_rate',$invoice->sgst_rate ?? 0) }}"></div><div><label>IGST Rate %</label><input type="number" min="0" max="100" step="0.01" name="igst_rate" value="{{ old('igst_rate',$invoice->igst_rate ?? 0) }}"></div><div><label>Round Off (+/-)</label><input type="number" step="0.01" name="round_off" value="{{ old('round_off',$invoice->round_off ?? 0) }}"></div></div><p class="mt-4 text-sm text-neutral-500">Totals shown while editing are estimates. The server recalculates every amount before saving.</p><p class="mt-2 text-xl font-black">Estimated total: ₹<span id="estimate">0.00</span></p></section>
    <section class="card p-6"><h2 class="mb-4 text-lg font-black">5. Bank / Payment Details</h2><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3">@foreach(['bank_holder_snapshot'=>'Account Holder','bank_name_snapshot'=>'Bank Name','bank_account_snapshot'=>'Account Number','bank_ifsc_snapshot'=>'IFSC','bank_branch_snapshot'=>'Branch','upi_id_snapshot'=>'UPI ID'] as $field=>$label)<div><label>{{ $label }}</label><input name="{{ $field }}" value="{{ old($field,$invoice->$field ?? match($field){'bank_holder_snapshot'=>$agency->bank_account_holder_name,'bank_name_snapshot'=>$agency->bank_name,'bank_account_snapshot'=>$agency->bank_account_number,'bank_ifsc_snapshot'=>$agency->bank_ifsc,'bank_branch_snapshot'=>$agency->bank_branch,'upi_id_snapshot'=>$agency->upi_id}) }}"></div>@endforeach</div><p class="mt-3 text-sm text-neutral-500">UPI QR, agency logo, signature and stamp are copied from Agency Settings when the invoice is created.</p></section>
