<script>
(() => {
 const rows=document.getElementById('itemRows');let next=Math.max(-1,...Array.from(rows.querySelectorAll('[name^="items["]')).map(x=>Number(x.name.match(/^items\[(\d+)\]/)?.[1]??-1)))+1;
 const recalc=()=>{let sum=0;rows.querySelectorAll('.item-row').forEach(r=>{let amount=(Number(r.querySelector('.qty').value)||0)*(Number(r.querySelector('.rate').value)||0);r.querySelector('.amount').textContent=amount.toFixed(2);sum+=amount});let form=rows.closest('form'),val=n=>Number(form.elements[n]?.value)||0,type=form.elements.discount_type.value,discount=type==='percentage'?sum*val('discount_value')/100:type==='fixed'?val('discount_value'):0,taxable=Math.max(0,sum-discount),tax=form.elements.tax_type.value;document.getElementById('estimate').textContent=(taxable+taxable*(tax==='intra_state'?(val('cgst_rate')+val('sgst_rate')):tax==='inter_state'?val('igst_rate'):0)/100+val('round_off')).toFixed(2)};
 rows.addEventListener('input',recalc);rows.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')&&rows.children.length>1){e.target.closest('tr').remove();recalc()}});
 document.getElementById('addItem').onclick=()=>{let tr=document.createElement('tr');tr.className='item-row';tr.innerHTML=`<td class="p-1"><input required name="items[${next}][description]"></td><td class="p-1"><input name="items[${next}][hsn_sac_code]"></td><td class="p-1"><input class="qty" required min="0.01" step="0.01" type="number" name="items[${next}][quantity]" value="1"></td><td class="p-1"><input name="items[${next}][unit]"></td><td class="p-1"><input class="rate" required min="0" step="0.01" type="number" name="items[${next}][rate]" value="0"></td><td class="p-1 font-bold amount">0.00</td><td class="p-1"><button type="button" class="remove-row text-red-600">Remove</button><input type="hidden" name="items[${next}][service_id]"></td>`;rows.append(tr);next++};
 rows.closest('form').addEventListener('input',recalc);recalc();
 const customer=document.getElementById('customer'),assignment=document.getElementById('assignment'),agreement=document.getElementById('agreement'),requirement=document.getElementById('requirement');
 const setCustomer=()=>{let o=customer.selectedOptions[0];if(!o?.value)return;document.getElementById('customerName').value=o.dataset.name||'';document.getElementById('customerAddress').value=o.dataset.address||'';document.getElementById('customerMobile').value=o.dataset.mobile||'';document.getElementById('customerEmail').value=o.dataset.email||''};
 customer.addEventListener('change',setCustomer);
 const setCharge=o=>{if({{ $invoice->exists ? 'true' : 'false' }} || !o?.value)return;let r=rows.querySelector('.item-row'),d=r?.querySelector('[name$="[description]"]'),rate=r?.querySelector('.rate');if(!r||!d||!rate||d.value.trim())return;let salary=Number(o.dataset.salary)||0,charge=Number(o.dataset.charge)||0;if(salary>0){d.value='Monthly Worker Salary';rate.value=o.dataset.salary;let service=r.querySelector('[name$="[service_id]"]');if(service)service.value=o.dataset.service||'';if(charge>0){document.getElementById('addItem').click();r=rows.lastElementChild;d=r.querySelector('[name$="[description]"]');rate=r.querySelector('.rate')}}if(charge>0){d.value='Monthly Agency Service Charge';rate.value=o.dataset.charge;let service=r.querySelector('[name$="[service_id]"]');if(service)service.value=o.dataset.service||''}recalc()};
 assignment.addEventListener('change',()=>{let o=assignment.selectedOptions[0];if(o?.value){customer.value=o.dataset.customer;requirement.value=o.dataset.requirement||'';setCustomer();setCharge(o)}});
 agreement.addEventListener('change',()=>{let o=agreement.selectedOptions[0];if(o?.value){customer.value=o.dataset.customer;assignment.value=o.dataset.assignment||'';requirement.value=o.dataset.requirement||assignment.selectedOptions[0]?.dataset.requirement||'';setCustomer();setCharge(o)}});
})();
</script>
